// BUG 1: returns lowercase instead of capitalizing first letter
export function capitalize(s: string): string {
  if (!s) return s;
  return s[0].toLowerCase() + s.slice(1);
}

// BUG 2: truncates at length+1 instead of length
export function truncate(s: string, length: number): string {
  if (s.length <= length) return s;
  return s.slice(0, length + 1) + '...';
}

// BUG 3: does not lowercase before palindrome check
export function isPalindrome(s: string): boolean {
  const cleaned = s.replace(/[^a-zA-Z0-9]/g, '');
  return cleaned === cleaned.split('').reverse().join('');
}

